$rulesSource=$gameDisplayMode.'|'.$gamesPerPortal.'|'.$gameOrderMode.'|'.implode(',',array_map(static fn($g)=>(int)$g['id'].':'.(int)$g['sort_order'],$allGames));$rulesHash=hash('sha256',$rulesSource);$games=$allGames;
if($player){
