    $st=$pdo->prepare('SELECT ga.rules_hash,g.id,g.title,g.slug,g.game_type,g.category,g.difficulty,g.intro,g.time_limit_seconds,g.sound_enabled,g.content_json,g.sort_order FROM game_assignments ga JOIN games g ON g.id=ga.game_id AND g.active=1 WHERE ga.employee_id=? ORDER BY ga.position,ga.id');$st->execute([(int)$player['id']]);$assignedRows=$st->fetchAll();$assignmentHash=$assignedRows?(string)$assignedRows[0]['rules_hash']:'';
